//#region src/images/images-optimizer.runtime.ts
/** Default Cloudflare Images binding name on the Worker `env`. */
const DEFAULT_BINDING = "IMAGES";
const createCloudflareImageOptimizer = ({ env, options }) => {
	const binding = options?.binding ?? DEFAULT_BINDING;
	const images = env?.[binding];
	if (!images || typeof images.input !== "function") throw new Error(`[vinext] The Cloudflare image optimizer requires an \`${binding}\` Images binding.\n  Add it to wrangler.jsonc:\n    "images": { "binding": "${binding}" }`);
	return { async transformImage(body, { width, format, quality }) {
		return (await images.input(body).transform(width > 0 ? { width } : {}).output({
			format,
			quality
		})).response();
	} };
};
//#endregion
export { createCloudflareImageOptimizer as default };
