//#region src/server/workers-tracing.ts
function readExceptionField(error, key) {
	try {
		return Reflect.get(error, key);
	} catch {
		return;
	}
}
function normalizeException(error) {
	if (typeof error === "string") return error;
	if (error && typeof error === "object") {
		const code = readExceptionField(error, "code");
		const name = readExceptionField(error, "name");
		const message = readExceptionField(error, "message");
		const stack = readExceptionField(error, "stack");
		const details = {
			...typeof name === "string" ? { name } : {},
			...typeof message === "string" ? { message } : {},
			...typeof stack === "string" ? { stack } : {}
		};
		if (typeof code === "string" || typeof code === "number") return {
			...details,
			code
		};
		if (typeof name === "string") return {
			...details,
			name
		};
		if (typeof message === "string") return {
			...details,
			message
		};
	}
	try {
		return String(error);
	} catch {
		return "Unknown exception";
	}
}
function createWorkersTracingIntegration(tracing) {
	const backendSpan = (span) => ({
		recordException: (error) => {
			if (span.isTraced) span.recordException?.(normalizeException(error));
		},
		setAttribute: (key, value) => span.setAttribute(key, value),
		setErrorStatus: (message) => span.setStatus?.({
			code: "error",
			message
		}),
		updateName: (name) => span.updateName?.(name)
	});
	return {
		id: "cloudflare-workers",
		getActiveSpan() {
			const span = tracing.getActiveSpan?.();
			return span ? backendSpan(span) : void 0;
		},
		enterSpan(descriptor, callback) {
			return tracing.enterSpan(descriptor.name, (span) => {
				for (const [key, value] of Object.entries(descriptor.attributes)) span.setAttribute(key, value);
				return callback(backendSpan(span));
			});
		}
	};
}
//#endregion
export { createWorkersTracingIntegration };
